    let mut rows=String::from("case,allowed,relics,allies,seed,kind,index\n");for case in 0..3840usize {let mut s=State::default();s.entry.allowed_types=((case/256+1)*16) as u8;s.entry.party_relics=(case/16%4) as u8;s.living.allies=(case/64%5) as u8;s.rng.index=case as u8;s.choose_type(&table)?;writeln!(rows,"{case},{},{},{},{},{},{}",s.entry.allowed_types,s.entry.party_relics,s.living.allies,case as u8,s.entry.battle_type,s.rng.index).unwrap();}fs::write(dir.join("types.csv"),rows).map_err(|e|e.to_string())
